entries[72] = { ["name"] = "Schildhieb", ["text"] = "10 Wut Nahkampfreichweite\nSpontanzauber 12 sek. Abklingzeit\nBenötigt Kampfhaltung, Verteidigungshaltung\nSchlägt mit Eurem Schild auf das Ziel ein und macht es benommen. Unterbricht das Wirken von Zaubern und verhindert 6 sec lang, dass diese Art Zauber gewirkt werden kann." }
entries[75] = { ["name"] = "Automatischer Schuss", ["text"] = "35 Meter Reichweite\nBenötigt Distanzwaffe\nSchießt automatisch auf das Ziel, bis die Aktion abgebrochen wird. Alle Distanzangriffe eines Jägers haben ein um 15% erhöhtes Angriffstempo." }
