entries[99] = { ["name"] = "Demoralisierendes Gebrüll", ["text"] = "10 Wut\nSpontanzauber\nBenötigt Bärengestalt, Terrorbärengestalt\nDer Druide brüllt und verringert damit die Nahkampfangriffskraft von in der Nähe befindlichen Feinden um 41. Hält 30 sec lang an." }
