entries[603] = { ["name"] = "Fluch der Verdammnis", ["text"] = "15% von Grundmana 30 Meter Reichweite\nSofort 1 min Abklingzeit\nVerflucht das Ziel mit drohender Verdammnis und verursacht nach Ablauf von 1 min 3200 Schattenschaden. Wenn das Ziel Erfahrung oder Ehre gewährt und durch diesen Schaden stirbt, wird eine Verdammniswache beschworen. Kann nicht auf Spieler gewirkt werden." }
