entries[642] = { ["name"] = "Gottesschild", ["text"] = "3% von Grundmana\nSofort 5 min Abklingzeit\nSchützt den Paladin 12 sec lang vor allen Schäden und Zaubern, verringert jedoch seinen verursachten Schaden um 50%. Einmal geschützt, kann der Paladin 2 min lang nicht erneut zum Ziel von 'Gottesschild', 'Göttlicher Schutz' oder 'Hand des Schutzes' werden. Kann innerhalb von 30 sec nach 'Zornige Vergeltung' nicht genutzt werden." }
entries[643] = { ["name"] = "Aura der Hingabe", ["text"] = "Sofort\nGibt Gruppen- und Schlachtzugsmitgliedern in einem Umkreis von 40 Metern 275 zusätzliche Rüstung. Spieler können pro Paladin immer nur jeweils eine Aura besitzen." }
