entries[687] = { ["name"] = "Dämonenhaut", ["text"] = "31% von Grundmana\nSofort\nSchützt den Zaubernden, erhöht die Rüstung um 90 und erhöht die durch Zauber und Effekte erzeugte Gesundheit um 20%. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Hexenmeister aktiv sein. Hält 30 min an." }
entries[688] = { ["name"] = "Wichtel beschwören", ["text"] = "64% von Grundmana\nWirken in 10 sek.\nBeschwört einen Wichtel, der unter dem Befehl des Hexenmeisters steht." }
