entries[701] = { ["name"] = "Feuerblitz", ["text"] = "10 Mana 30 Meter Reichweite\nWirken in 1.5 sek.\nÜberzieht ein Ziel mit 19 Feuerschaden." }
entries[702] = { ["name"] = "Fluch der Schwäche", ["text"] = "10% von Grundmana 30 Meter Reichweite\nSofort\nDie Nahkampfangriffskraft des Ziels wird um 21 verringert, seine Rüstung um 5%. Hält 2 min lang an. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[703] = { ["name"] = "Erdrosseln", ["text"] = "50 Energie Nahkampfreichweite\nSofort\nBenötigt Verstohlenheit\nErdrosselt den Feind, verursacht im Verlauf von 18 sec insgesamt [(20 + Attack power * 0.07) * 6] Schaden, erhöht durch Eure Angriffskraft. Muss verstohlen und hinter dem Ziel sein. Gewährt 1 Combopunkt." }
entries[705] = { ["name"] = "Schattenblitz", ["text"] = "16% von Grundmana 30 Meter Reichweite\nWirken in 2.8 sek.\nSendet einen schattigen Blitz zum Gegner, der 52 to 61 Schattenschaden verursacht." }
