entries[707] = { ["name"] = "Feuerbrand", ["text"] = "17% von Grundmana 30 Meter Reichweite\nWirken in 2 sek.\nVerbrennt den Feind und fügt 24 Feuerschaden sowie 15 sec lang insgesamt 40 zusätzlichen Feuerschaden zu." }
entries[709] = { ["name"] = "Blutsauger", ["text"] = "17% von Grundmana 30 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nÜberträgt alle 1 Sek. 29 Gesundheit vom Ziel auf den Zaubernden. Hält 5 sec lang an." }
