entries[720] = { ["name"] = "Umschlingen", ["text"] = "Sofort\nDie Brutstätte Fankriss' des Unnachgiebigen zieht das Ziel nahen Silithidjungtieren entgegen und wurzelt es 8 sec lang fest." }
entries[724] = { ["name"] = "Brunnen des Lichts", ["text"] = "17% von Grundmana 40 Meter Reichweite\nWirken in 0.5 sek. 3 min Abklingzeit\nErschafft einen heiligen Brunnen des Lichts. Befreundete Spieler können den Brunnen des Lichts anklicken, um im Verlauf von 6 sec insgesamt 801 Gesundheit wiederherzustellen. Erlittener Schaden, der 30% Eurer gesamten Gesundheit entspricht, bricht den Effekt ab. Der Brunnen des Lichts bleibt 3 min lang bestehen oder bis 10 Aufladungen verbraucht sind." }
