entries[759] = { ["name"] = "Manaedelstein herbeizaubern", ["text"] = "75% von Grundmana\nWirken in 3 sek.\nZaubert einen Manaachat herbei, der zum sofortigen Wiederherstellen von 390 to 410 Mana verwendet werden kann." }
entries[768] = { ["name"] = "Katzengestalt", ["text"] = "35% von Grundmana\nSofort\nVerwandelt Euch in eine Katzengestalt und erhöht die Nahkampfangriffskraft um 40 plus Beweglichkeit. Beschützt den Zaubernden auch vor Verwandlungseffekten und erlaubt den Einsatz von verschiedenen Katzenfähigkeiten.\n\nDer Akt des Gestaltwandelns befreit den Zaubernden von Verwandlungs- und bewegungseinschränkenden Effekten." }
entries[769] = { ["name"] = "Prankenhieb (Bär)", ["text"] = "20 Wut 8 Meter Reichweite\nSpontanzauber\nBenötigt Bärengestalt, Terrorbärengestalt\nSchlägt in der Nähe befindliche Feinde und verursacht 19 Schaden. Der Schaden wird durch Angriffskraft erhöht." }
entries[770] = { ["name"] = "Feenfeuer", ["text"] = "8% von Grundmana 30 Meter Reichweite\nSofort\nVerringert die Rüstung des Ziels 5 min lang um 5%. Während der Wirkungsdauer kann das Ziel weder Verstohlenheit anwenden noch unsichtbar werden." }
entries[772] = { ["name"] = "Verwunden", ["text"] = "10 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung, Verteidigungshaltung\nVerwundet das Ziel und lässt es 15 sec lang für 25 Schaden plus zusätzlich [0.2 * 5 * ((Mainhand weapon max base damage + Mainhand weapon min base damage) / 2 + Attack power / 14 * Mainhand weapon base speed)] Schaden bluten (basierend auf Waffenschaden)." }
entries[774] = { ["name"] = "Verjüngung", ["text"] = "18% von Grundmana 40 Meter Reichweite\nSofort\nHeilt im Verlauf von 15 sec um [Quellwert] Gesundheit.", ["unresolvedValues"] = true }
entries[779] = { ["name"] = "Prankenhieb (Bär)", ["text"] = "20 Wut 8 Meter Reichweite\nSpontanzauber\nBenötigt Bärengestalt, Terrorbärengestalt\nSchlägt in der Nähe befindliche Feinde und verursacht 9 Schaden. Der Schaden wird durch Angriffskraft erhöht." }
entries[780] = { ["name"] = "Prankenhieb (Bär)", ["text"] = "20 Wut 8 Meter Reichweite\nSpontanzauber\nBenötigt Bärengestalt, Terrorbärengestalt\nSchlägt in der Nähe befindliche Feinde und verursacht 13 Schaden. Der Schaden wird durch Angriffskraft erhöht." }
entries[781] = { ["name"] = "Rückzug", ["text"] = "5% von Grundmana Unbegrenzte Reichweite\nSofort 25 sek. Abklingzeit\nIhr versucht, Euch mit einem Rückwärtssprung aus dem Kampf zurückzuziehen. Kann nur im Kampf genutzt werden." }
entries[782] = { ["name"] = "Dornen", ["text"] = "17% von Grundmana 30 Meter Reichweite\nSofort\nAus dem befreundeten Ziel sprießen Dornen, die jedem Angreifer 6 Naturschaden zufügen. Hält 10 min lang an." }
entries[783] = { ["name"] = "Reisegestalt", ["text"] = "13% von Grundmana\nSofort\nVerwandelt Euch in eine Reisegestalt und erhöht Euer Bewegungstempo um 40%. Beschützt den Zaubernden auch vor Verwandlungseffekten. Kann nur draußen verwendet werden.\n\nDer Akt des Gestaltwandelns befreit den Zaubernden von Verwandlungs- und bewegungseinschränkenden Effekten." }
entries[785] = { ["name"] = "Wahre Erfüllung", ["text"] = "260 Mana 45 Meter Reichweite\nWirken in 0.5 sek.\nVon den Kräften des Propheten Skeram bekehrt, wird das Ziel mit heiliger Macht erfüllt. Die Zauber des Ziels werden sofort gewirkt, der verursachte Schaden ist um 300%, alle Widerstände um 50 und das Bewegungstempo um 40% erhöht. Hält 20 sec lang an." }
