entries[833] = { ["name"] = "Grüntee", ["text"] = "Sofort\nHeilt sofort 30 Schaden. Stellt im Verlauf von 10 sec insgesamt 60 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
