entries[837] = { ["name"] = "Frostblitz", ["text"] = "8% von Grundmana 30 Meter Reichweite\nWirken in 2.2 sek.\nSchleudert einen Frostblitz auf den Feind, der [Quellwert] bis [Quellwert] Frostschaden verursacht und sein Bewegungstempo 6 sec lang um 40% verringert.", ["unresolvedValues"] = true }
entries[845] = { ["name"] = "Spalten", ["text"] = "20 Wut Nahkampfreichweite\nNächster Nahkampf\nBenötigt Nahkampfwaffe\nEin weitreichender Angriff, der dem Ziel und\n\nGlyphe 'Spalten'\nseinen nächsten zwei Verbündeten\n\nseinem nächsten Verbündeten Waffenschaden plus 15 zufügt." }
entries[851] = { ["name"] = "Verwandlung: Schaf", ["text"] = "200 Mana 20 Meter Reichweite\nSofort\nVerwandelt den Feind bis zu 10 sec lang in ein hilfloses Schaf, das weder Zauber wirken noch angreifen kann und sich um 60% langsamer bewegt." }
entries[853] = { ["name"] = "Hammer der Gerechtigkeit", ["text"] = "3% von Grundmana 10 Meter Reichweite\nSofort 1 min Abklingzeit\nBetäubt das Ziel 3 sec lang und unterbricht 3 sec lang das Zauberwirken eines Nichtspieler-Ziels." }
entries[857] = { ["name"] = "Khadgars Öffnung", ["text"] = "10% von Grundmana 5 Meter Reichweite\nWirken in 10 sek.\nReagenzien:\nWinziger Eisenschlüssel\nSchließt auf magische Weise Schatztruhen und andere verschlossene Gegenstände auf." }
entries[865] = { ["name"] = "Frostnova", ["text"] = "7% von Grundmana\nSofort 25 sek. Abklingzeit\nFügt in der Nähe des Zaubernden befindlichen Feinden [Quellwert] bis [Quellwert] Frostschaden zu und friert sie bis zu 8 sec lang ein. Erlittener Schaden kann den Effekt unterbrechen.", ["unresolvedValues"] = true }
entries[871] = { ["name"] = "Schildwall", ["text"] = "Sofort 5 min Abklingzeit\nBenötigt Verteidigungshaltung\nVerringert jeglichen erlittenen Schaden 12 sec lang um 60%." }
entries[879] = { ["name"] = "Exorzismus", ["text"] = "8% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek. 15 sek. Abklingzeit\nVerursacht (96 + 0.15 * Spell power + 0.15 * Attack power) bis (110 + 0.15 * Spell power + 0.15 * Attack power) Heiligschaden an einem feindlichen Ziel. Ist das Ziel untot oder dämonisch wird der Zauber stets kritisch treffen." }
entries[883] = { ["name"] = "Tier rufen", ["text"] = "Sofort\nBeschwört Euer Tier zu Euch." }
entries[886] = { ["name"] = "Unsichtbarkeit", ["text"] = "Wirken in 3 sek.\nLehrt 'Unsichtbarkeit'." }
entries[897] = { ["name"] = "Wütenden Programmierer beschwören" }
entries[898] = { ["name"] = "Inbrunst-Trank herstellen", ["text"] = "Wirken in 3 sek.\nReagenzien:\nFaustgroße Spinndrüse\nErstellt einen Trank der Inbrunst." }
entries[905] = { ["name"] = "Blitzschlagschild", ["text"] = "Sofort\nDer Zaubernde ist von 3 Kugelblitzen umgeben. Wenn der Zaubernde von einem Nahkampf-, Distanz- oder Zauberangriff getroffen wird, erleidet der Angreifende 51 Naturschaden. Dies kostet einen Kugelblitz. Es wird immer nur ein einzelner Kugelblitz alle paar Sekunden abgefeuert. Hält 10 min lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein.\n(3.5s Abklingzeit)" }
entries[913] = { ["name"] = "Welle der Heilung", ["text"] = "25% von Grundmana 40 Meter Reichweite\nWirken in 3 sek.\nHeilt ein befreundetes Ziel um 279 to 328." }
entries[915] = { ["name"] = "Blitzschlag", ["text"] = "10% von Grundmana 30 Meter Reichweite\nWirken in 2.5 sek.\nSchleudert einen Blitz auf das Ziel und fügt ihm 88 to 100 Naturschaden zu." }
entries[921] = { ["name"] = "Taschendiebstahl", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Verstohlenheit\nEinen Taschendiebstahl am Ziel begehen." }
entries[930] = { ["name"] = "Kettenblitzschlag", ["text"] = "26% von Grundmana 30 Meter Reichweite\nWirken in 2 sek. 6 sek. Abklingzeit\nSchleudert einen Blitzschlag auf den Feind, der 288 to 323 Naturschaden verursacht und zu in der Nähe befindlichen Feinden weiterspringt. Jeder Sprung verringert den Schaden um 30%. Wirkt auf insgesamt 3 Ziele." }
entries[932] = { ["name"] = "Geist auffüllen II", ["text"] = "30 Meter ReichweiteWirken in 3 sek. 6 min Abklingzeit\nStellt Mana des Ziels wieder her." }
entries[939] = { ["name"] = "Welle der Heilung", ["text"] = "25% von Grundmana 40 Meter Reichweite\nWirken in 3 sek.\nHeilt ein befreundetes Ziel um 389 to 454." }
entries[943] = { ["name"] = "Blitzschlag", ["text"] = "10% von Grundmana 30 Meter Reichweite\nWirken in 2.5 sek.\nSchleudert einen Blitz auf das Ziel und fügt ihm 131 to 149 Naturschaden zu." }
entries[945] = { ["name"] = "Blitzschlagschild", ["text"] = "Sofort\nDer Zaubernde ist von 3 Kugelblitzen umgeben. Wenn der Zaubernde von einem Nahkampf-, Distanz- oder Zauberangriff getroffen wird, erleidet der Angreifende 80 Naturschaden. Dies kostet einen Kugelblitz. Es wird immer nur ein einzelner Kugelblitz alle paar Sekunden abgefeuert. Hält 10 min lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein.\n(3.5s Abklingzeit)" }
