entries[970] = { ["name"] = "Schattenwort: Schmerz", ["text"] = "22% von Grundmana 30 Meter Reichweite\nSofort\nEin Wort der Dunkelheit, das 18 sec lang insgesamt 120 Schattenschaden zufügt." }
entries[974] = { ["name"] = "Erdschild", ["text"] = "15% von Grundmana 40 Meter Reichweite\nSofort\nSchützt das Ziel mit einem Erdschild, der die erhöhte Zauberdauer oder verringerte Kanalisierungsdauer durch erlittenen Schaden um 30% verringert und Angriffe das geschützte Ziel um 150 heilen lässt. Dieser Effekt tritt nur einmal alle paar Sekunden auf. 6 Aufladungen. Hält 10 min lang an. Der Erdschild kann immer nur auf einem Ziel gleichzeitig aktiv sein, und auf jedem Ziel kann nur ein Elementarschild aktiv sein.\n(3.5s Abklingzeit)" }
entries[976] = { ["name"] = "Schattenschutz", ["text"] = "31% von Grundmana 30 Meter Reichweite\nSofort\nErhöht 10 min lang die Widerstandskraft des Ziels gegen alle Schattenzauber um 30." }
entries[980] = { ["name"] = "Fluch der Pein", ["text"] = "10% von Grundmana 30 Meter Reichweite\nSofort\nVerflucht das Ziel mit Pein und fügt 24 sec lang insgesamt 84 Schattenschaden zu. Zuerst wird der Schaden langsam zugefügt und nimmt dann zu, bis der Fluch seine Gesamtdauer erreicht hat. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[982] = { ["name"] = "Tier wiederbeleben", ["text"] = "80% von Grundmana\nWirken in 10 sek.\nBringt Euer totes Tier mit 15% seiner Grundgesundheit wieder ins Leben zurück." }
entries[984] = { ["name"] = "Göttliche Pein", ["text"] = "15% von Grundmana 30 Meter Reichweite\nWirken in 2.5 sek.\nZerschmettert einen Feind und fügt ihm 97 to 112 Heiligschaden zu." }
entries[988] = { ["name"] = "Magiebannung", ["text"] = "14% von Grundmana 30 Meter Reichweite\nSofort\nBannt auf dem Ziel liegende Magie und entfernt 2 schädliche Zauber von einem Freund oder 2 nützliche Zauber von einem Feind." }
entries[990] = { ["name"] = "Essen herbeizaubern", ["text"] = "40% von Grundmana\nWirken in 3 sek.\nZaubert 20 Laibe Roggenbrot herbei und versorgt den Magier sowie seine Verbündeten mit etwas Essbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[992] = { ["name"] = "Schattenwort: Schmerz", ["text"] = "22% von Grundmana 30 Meter Reichweite\nSofort\nEin Wort der Dunkelheit, das 18 sec lang insgesamt 210 Schattenschaden zufügt." }
entries[996] = { ["name"] = "Gebet der Heilung", ["text"] = "48% von Grundmana 40 Meter Reichweite\nWirken in 3 sek.\nEin machtvolles Gebet heilt alle Gruppenmitglieder des befreundeten Ziels in einem Umkreis von 30 Metern um 458 to 487." }
entries[1002] = { ["name"] = "Augen des Wildtiers", ["text"] = "1% von Grundmana Unbegrenzte Reichweite\nWirken in 2 sek.\nLässt Euch die direkte Kontrolle über Euer Tier übernehmen und 1 min lang durch seine Augen sehen." }
entries[1004] = { ["name"] = "Göttliche Pein", ["text"] = "15% von Grundmana 30 Meter Reichweite\nWirken in 2.5 sek.\nZerschmettert einen Feind und fügt ihm 158 to 178 Heiligschaden zu." }
entries[1006] = { ["name"] = "Inneres Feuer", ["text"] = "14% von Grundmana\nSofort\nDer Zaubernde wird von einem Schub heiliger Energie erfüllt, der seine Rüstung um 945 erhöht. Ein erlittener Nahkampf- oder Distanzangriffstreffer verbraucht eine Aufladung. Hält 30 min lang an oder bis alle 20 Aufladungen verbraucht sind." }
entries[1008] = { ["name"] = "Magie verstärken", ["text"] = "27% von Grundmana 30 Meter Reichweite\nSofort\nVerstärkt gegen das anvisierte Gruppenmitglied gerichtete Magie, wobei der von Zaubern zugefügte Schaden um bis zu 15 und Heilzauber um bis zu 16 erhöht werden. Hält 10 min lang an." }
entries[1010] = { ["name"] = "Fluch der Torheit", ["text"] = "110 Mana 30 Meter Reichweite\nSofort\nVerflucht das Ziel mit Torheit, verringert Intelligenz und Willenskraft alle 3 Sek. um 6, bis beides um insgesamt 90 verringert worden ist. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[1014] = { ["name"] = "Fluch der Pein", ["text"] = "10% von Grundmana 30 Meter Reichweite\nSofort\nVerflucht das Ziel mit Pein und fügt 24 sec lang insgesamt 180 Schattenschaden zu. Zuerst wird der Schaden langsam zugefügt und nimmt dann zu, bis der Fluch seine Gesamtdauer erreicht hat. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[1022] = { ["name"] = "Hand des Schutzes", ["text"] = "6% von Grundmana 30 Meter Reichweite\nSofort 5 min Abklingzeit\nEin anvisiertes Gruppen- oder Schlachtzugsmitglied ist 6 sec lang vor allen körperlichen Angriffen geschützt, allerdings kann es dabei weder angreifen noch körperliche Fähigkeiten einsetzen. Spieler können pro Paladin immer nur von einer Hand berührt werden. Einmal geschützt, kann das Ziel 2 min lang nicht erneut zum Ziel von 'Gottesschild', 'Göttlicher Schutz' oder 'Hand des Schutzes' werden. Haben Spieler innerhalb der letzten 30 sec 'Zornige Vergeltung' genutzt, können sie ebenfalls nicht zum Ziel von 'Hand des Schutzes' werden." }
entries[1026] = { ["name"] = "Heiliges Licht", ["text"] = "29% von Grundmana 40 Meter Reichweite\nWirken in 2.5 sek.\nHeilt ein befreundetes Ziel um 409 to 467." }
entries[1032] = { ["name"] = "Aura der Hingabe", ["text"] = "Sofort\nGibt Gruppen- und Schlachtzugsmitgliedern in einem Umkreis von 40 Metern 505 zusätzliche Rüstung. Spieler können pro Paladin immer nur jeweils eine Aura besitzen." }
entries[1035] = { ["name"] = "Feuerzauberschutz" }
entries[1038] = { ["name"] = "Hand der Erlösung", ["text"] = "6% von Grundmana 30 Meter Reichweite\nSofort 2 min Abklingzeit\nLegt eine Hand auf das Gruppen- und Schlachtzugsmitglied und verringert 10 sec lang alle 1 Sek. seine gesamte Bedrohung um 2%. Spieler können pro Paladin immer nur von einer Hand berührt werden." }
entries[1042] = { ["name"] = "Heiliges Licht", ["text"] = "29% von Grundmana 40 Meter Reichweite\nWirken in 2.5 sek.\nHeilt ein befreundetes Ziel um 643 to 724." }
entries[1044] = { ["name"] = "Hand der Freiheit", ["text"] = "6% von Grundmana 30 Meter Reichweite\nSofort 25 sek. Abklingzeit\nLegt eine Hand auf ein freundliches Ziel und gewährt ihm so 6 sec lang Immunität gegen jegliche bewegungseinschränkende Effekte. Spieler können pro Paladin immer nur von einer Hand berührt werden." }
entries[1050] = { ["name"] = "Opferung", ["text"] = "Wirken in 1 sek." }
entries[1058] = { ["name"] = "Verjüngung", ["text"] = "18% von Grundmana 40 Meter Reichweite\nSofort\nHeilt im Verlauf von 15 sec um [Quellwert] Gesundheit.", ["unresolvedValues"] = true }
entries[1062] = { ["name"] = "Wucherwurzeln", ["text"] = "7% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek.\nLässt das Ziel an Ort und Stelle festwurzeln und verursacht im Verlauf von 15 sec insgesamt 50 Naturschaden. Erlittener Schaden kann den Effekt unterbrechen." }
entries[1064] = { ["name"] = "Kettenheilung", ["text"] = "19% von Grundmana 40 Meter Reichweite\nWirken in 2.5 sek.\nHeilt das befreundete Ziel um 332 to 381 und springt dann weiter, um weitere in der Nähe befindliche Ziele zu heilen. Wenn es auf ein Gruppenmitglied gewirkt wird, springt die Heilung nur auf andere Gruppenmitglieder über. Nach jedem Sprung verringert sich die Heilwirkung um 40%. Heilt 3 Ziele insgesamt." }
entries[1066] = { ["name"] = "Wassergestalt", ["text"] = "13% von Grundmana\nSofort\nVerwandelt Euch in eine Wassergestalt. Das Schwimmtempo wird um 50% erhöht und der Druide kann unter Wasser atmen. Beschützt den Zaubernden auch vor Verwandlungseffekten.\n\nDer Akt des Gestaltwandelns befreit den Zaubernden von Verwandlungs- und bewegungseinschränkenden Effekten." }
entries[1075] = { ["name"] = "Dornen", ["text"] = "17% von Grundmana 30 Meter Reichweite\nSofort\nAus dem befreundeten Ziel sprießen Dornen, die jedem Angreifer 9 Naturschaden zufügen. Hält 10 min lang an." }
entries[1079] = { ["name"] = "Zerfetzen", ["text"] = "30 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nFinishing-Move, der Schaden im Lauf der Zeit verursacht. Der Schaden erhöht sich pro Combopunkt sowie durch Eure Angriffskraft:\n1 Punkt: [(3 + 4 * 1 + 0.01 * Attack power) * 6 ] Schaden im Verlauf von 12 sec.\n2 Punkte: [(3 + 4 * 2 + 0.02 * Attack power) * 6 ] Schaden im Verlauf von 12 sec.\n3 Punkte: [(3 + 4 * 3 + 0.03 * Attack power) * 6 ] Schaden im Verlauf von 12 sec.\n4 Punkte: [(3 + 4 * 4 + 0.04 * Attack power) * 6 ] Schaden im Verlauf von 12 sec.\n5 Punkte: [(3 + 4 * 5 + 0.05 * Attack power) * 6 ] Schaden im Verlauf von 12 sec." }
entries[1082] = { ["name"] = "Klaue", ["text"] = "45 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nDen Feind mit Klauen beharken und ihm so zusätzlich 27 Schaden zufügen. Gewährt 1 Combopunkt." }
entries[1086] = { ["name"] = "Dämonenrüstung", ["text"] = "31% von Grundmana\nSofort\nSchützt den Zaubernden, erhöht die Rüstung um 660 und erhöht die durch Zauber und Effekte erzeugte Gesundheit um 20%. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Hexenmeister aktiv sein. Hält 30 min an." }
entries[1088] = { ["name"] = "Schattenblitz", ["text"] = "17% von Grundmana 30 Meter Reichweite\nWirken in 3 sek.\nSendet einen schattigen Blitz zum Gegner, der 92 to 104 Schattenschaden verursacht." }
entries[1090] = { ["name"] = "Schlaf", ["text"] = "90 Mana 30 Meter Reichweite\nWirken in 1.5 sek.\nVersetzt das feindliche Ziel bis zu 30 sec lang in Schlaf. Jeglicher zugefügte Schaden wird das Ziel wieder aufwecken. Es kann immer nur jeweils ein Ziel schlafen." }
entries[1094] = { ["name"] = "Feuerbrand", ["text"] = "17% von Grundmana 30 Meter Reichweite\nWirken in 2 sek.\nVerbrennt den Feind und fügt 53 Feuerschaden sowie 15 sec lang insgesamt 90 zusätzlichen Feuerschaden zu." }
entries[1098] = { ["name"] = "Dämon unterwerfen", ["text"] = "27% von Grundmana 30 Meter Reichweite\nWirken in 3 sek.\nReagenzien:\nSeelensplitter" }
entries[1106] = { ["name"] = "Schattenblitz", ["text"] = "17% von Grundmana 30 Meter Reichweite\nWirken in 3 sek.\nSendet einen schattigen Blitz zum Gegner, der 150 to 170 Schattenschaden verursacht." }
entries[1108] = { ["name"] = "Fluch der Schwäche", ["text"] = "10% von Grundmana 30 Meter Reichweite\nSofort\nDie Nahkampfangriffskraft des Ziels wird um 41 verringert, seine Rüstung um 5%. Hält 2 min lang an. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[1120] = { ["name"] = "Seelendieb", ["text"] = "14% von Grundmana 30 Meter Reichweite\nKanalisiert (Wirken in 15 sek.)\nEntzieht dem Ziel die Seele und verursacht 15 sec lang insgesamt 55 Schattenschaden. Besitzt das Ziel 25% Gesundheit oder weniger, verursacht 'Seelendieb' den vierfachen Schaden. Wenn das Ziel beim Entziehen der Seele stirbt und Erfahrung oder Ehrenpunkte abgibt, erhält der Zaubernde einen Seelensplitter. Jedes Mal, wenn 'Seelendieb' Schaden verursacht, besteht ebenfalls eine Chance, dass ein Seelensplitter erzeugt wird. Seelensplitter werden für andere Zauber benötigt." }
entries[1121] = { ["name"] = "Umschlingen", ["text"] = "100 Meter Reichweite\nSofort\nDie Brutstätte Fankriss' des Unnachgiebigen zieht das Ziel nahen Silithidjungtieren entgegen und wurzelt es 8 sec lang fest." }
entries[1122] = { ["name"] = "Inferno", ["text"] = "80% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek. 10 min Abklingzeit\nReagenzien:\nHöllenstein\nBeschwört einen Meteor aus dem wirbelnden Nether, der 200 Feuerschaden verursacht und alle feindlichen Ziele in dem Gebiet 2 sec lang betäubt. Aus dem Krater erhebt sich eine Höllenbestie, die 1 min lang unter dem Befehl des Zaubernden steht." }
entries[1126] = { ["name"] = "Mal der Wildnis", ["text"] = "24% von Grundmana 30 Meter Reichweite\nSofort\nErhöht 30 min lang die Rüstung des befreundeten Ziels um 25." }
entries[1127] = { ["name"] = "Essen", ["text"] = "Sofort 1 min Abklingzeit\nStellt im Verlauf von 27 sec insgesamt 874.8 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
