entries[1130] = { ["name"] = "Mal des Jägers", ["text"] = "2% von Grundmana 100 Meter Reichweite\nSofort\nBelegt das Ziel mit dem Mal des Jägers. Erhöht die Distanzangriffskraft aller Angreifer gegen dieses Ziel um 20. Zudem kann das Ziel dieser Fähigkeit stets vom Jäger gesehen werden, auch wenn es in den Verstohlenheitsmodus geht oder unsichtbar wird. Das Ziel wird außerdem auf der Minikarte angezeigt. Hält 5 min lang an." }
