entries[1462] = { ["name"] = "Wildtierkunde", ["text"] = "2% von Grundmana 40 Meter Reichweite\nSofort\nSammelt Informationen über das Zielwildtier. Der Tooltip zeigt Schaden, Gesundheit, Rüstung, alle Spezialwiderstände und Ernährung an. Zusätzlich wird angezeigt, ob das Tier zähmbar ist und über welche Fähigkeiten die gezähmte Kreatur verfügt." }
