entries[1485] = { ["name"] = "Rollender Brocken", ["text"] = "Unbegrenzte Reichweite\nWirken in 2 sek.\nFeuert mit einer Distanzwaffe auf das Ziel." }
entries[1490] = { ["name"] = "Fluch der Elemente", ["text"] = "10% von Grundmana 30 Meter Reichweite\nSofort\nVerflucht das Ziel und verringert 5 min lang seinen Arkan-, Feuer-, Frost-, Natur- und Schattenwiderstand um 45. Erhöht außerdem den erlittenen Magieschaden des Ziels um 6%. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[1494] = { ["name"] = "Wildtiere aufspüren", ["text"] = "Sofort 1.5 sek. Abklingzeit\nZeigt den Aufenthaltsort aller in der Nähe befindlichen Wildtiere auf der Minikarte an. Es kann immer nur jeweils eine Art des Fährtenlesens benutzt werden." }
entries[1495] = { ["name"] = "Mungobiss", ["text"] = "3% von Grundmana Nahkampfreichweite\nSofort 5 sek. Abklingzeit\nGreift den Feind an und verursacht (Attack power * 0.2 + 25) Schaden." }
entries[1499] = { ["name"] = "Eiskältefalle", ["text"] = "3% von Grundmana\nSofort 30 sek. Abklingzeit\nEine Eiskältefalle platzieren, die den ersten sich nähernden Feind einfriert und bis zu 10 sec lang jede Aktionen verhindert. Jeglicher verursachte Schaden wird das Eis brechen. Die Falle wird 30 sec lang bestehen bleiben. Es kann immer nur eine Falle aktiv sein." }
entries[1510] = { ["name"] = "Salve", ["text"] = "17% von Grundmana 35 Meter Reichweite\nBenötigt Distanzwaffe\nFeuert kontinuierlich eine Salve Munition auf das Zielgebiet. Fügt feindlichen Zielen im Umkreis von 8 Metern 6 sec lang alle 1.00 Sek. (Ranged attack power * 0.083700 + 52) Arkanschaden zu." }
entries[1513] = { ["name"] = "Wildtier ängstigen", ["text"] = "2% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek. 30 sek. Abklingzeit\nJagt einem Wildtier Angst ein, woraufhin es bis zu 10 sec lang voller Furcht wegläuft. Erlittener Schaden kann den Effekt unterbrechen. Es kann immer nur jeweils ein Wildtier mit dem Furchteffekt versehen werden." }
entries[1515] = { ["name"] = "Wildtier zähmen", ["text"] = "48% von Grundmana 30 Meter Reichweite\nKanalisiert (Wirken in 20 sek.)\nBeginnt mit dem Zähmen eines Wildtiers, damit es Euer Gefährte wird. Eure Rüstung ist um 100% verringert, während Ihr Euch 20 Sek. lang auf das Zähmen des Wildtiers fokussiert. Falls Ihr die Aufmerksamkeit des Wildtiers aus irgendeinem Grund verlieren solltet, schlägt der Vorgang der Zähmung fehl. Nachdem das Wildtier gezähmt ist, wird es sehr unzufrieden und nicht loyal sein. Füttert das Tier sofort, um es zufrieden zu stellen." }
entries[1516] = { ["name"] = "Schnellschuss", ["text"] = "5 - 30 Meter Reichweite\n1 min Abklingzeit\nBenötigt Distanzwaffe\nFeuert Eure Waffe sofort ab und verursacht so 5 zusätzlichen Schaden." }
entries[1528] = { ["name"] = "Meister befreien", ["text"] = "5 Meter Reichweite\nSofort\nBefreit Euren Meister von allen Fesseln." }
entries[1535] = { ["name"] = "Feuernova", ["text"] = "22% von Grundmana 30 Meter Reichweite\nSofort 10 sek. Abklingzeit\nLässt das aktive Feuertotem des Schamanen eine Feuerwelle ausstoßen, die allen Feinden innerhalb von 10 Metern um das Totem 53 to 62 Feuerschaden zufügt." }
