entries[1671] = { ["name"] = "Schildhieb", ["text"] = "10 Wut Nahkampfreichweite\nSpontanzauber 12 sek. Abklingzeit\nBenötigt Kampfhaltung, Verteidigungshaltung\nSchlägt mit Eurem Schild auf das Ziel ein und verursacht 18 Schaden. Unterbricht außerdem das Wirken von Zaubern und verhindert 6 sec lang, dass diese Art Zauber gewirkt werden kann." }
