entries[1680] = { ["name"] = "Wirbelwind", ["text"] = "25 WutSpontanzauber 10 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nBenötigt Berserkerhaltung\nIn einem stählernen Wirbel greift Ihr bis zu 4 Feinde in einem Umkreis von 8 Metern an und verursacht Waffenschaden beider Nahkampfwaffen bei jedem Feind." }
entries[1706] = { ["name"] = "Levitieren", ["text"] = "3% von Grundmana 30 Meter Reichweite\nSofort\nReagenzien:\nLeichte Feder\nErmöglicht es dem befreundeten Gruppen- oder Schlachtzugsmitglied, ein wenig über dem Boden zu schweben. Beim Levitieren fällt das Ziel zudem mit verringertem Tempo und kann sich über Wasser bewegen. Jeglicher Schaden hebt den Effekt auf. Hält 2 min lang an." }
