entries[1714] = { ["name"] = "Fluch der Sprachen", ["text"] = "4% von Grundmana 30 Meter Reichweite\nSofort\nZwingt das Ziel, Dämonisch zu sprechen, und verlangsamt die Zauberzeit um 25%. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem Ziel aktiv sein. Hält 30 sec lang an." }
entries[1715] = { ["name"] = "Kniesehne", ["text"] = "10 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung, Berserkerhaltung\nVerstümmelt den Feind, verringert 15 sec lang sein Bewegungstempo um 50%\n\nGlyphe 'Kniesehne'\nund hat eine Chance von 10%, das Ziel 5 sec lang bewegungsunfähig zu machen\n\n." }
entries[1719] = { ["name"] = "Tollkühnheit", ["text"] = "Sofort 5 min Abklingzeit\nBenötigt Berserkerhaltung\nEure nächsten 3 Angriffe mit Spezialfähigkeiten haben eine Chance von zusätzlichen 100%, einen kritischen Treffer zu erzielen. Euer erlittener Schaden wird jedoch um 20% erhöht. Hält 12 sec lang an." }
entries[1725] = { ["name"] = "Ablenken", ["text"] = "30 Energie 30 Meter Reichweite\nSofort 30 sek. Abklingzeit\nBewirkt eine Ablenkung, die die Aufmerksamkeit aller in der Nähe befindlichen Monster 10 Sek. lang auf sich zieht. Lässt Verstohlenheit weiterbestehen." }
entries[1735] = { ["name"] = "Demoralisierendes Gebrüll", ["text"] = "10 Wut\nSpontanzauber\nBenötigt Bärengestalt, Terrorbärengestalt\nDer Druide brüllt und verringert damit die Nahkampfangriffskraft von in der Nähe befindlichen Feinden um 61. Hält 30 sec lang an." }
